UPDATE app_user
SET username = #{username}, password_hash = #{password}, email = #{email}
WHERE user_id = #{userId} AND deleted_at IS NULL

mapper.select:
SELECT user_id, username, password_hash AS password, email, role, created_at
FROM app_user
WHERE deleted_at IS NULL

    AND user_id = #{userId}


    AND username LIKE CONCAT('%', #{username}, '%')


    AND email = #{email}


    AND role = #{role}


    AND created_at >= #{startTime}


    AND created_at = #{endTime}

SELECT COUNT(*) > 0 AS user_exists
FROM app_user
WHERE username = #{username}

SELECT user_id, username, password_hash AS password, email, role, created_at
FROM app_user
WHERE deleted_at IS NULL

    AND user_id = #{userId}


    AND username LIKE CONCAT('%', #{username}, '%')


    AND email = #{email}


    AND role = #{role}


    AND created_at >= #{startTime}


    AND created_at <= #{endTime}


    AND (
        created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND user_id < #{cursorUserId})
    )

ORDER BY created_at DESC, user_id DESC
LIMIT #{limit}

SELECT COUNT(*) > 0 AS user_exists
FROM app_user
WHERE email = #{email}
